/**
 * @file toastManager.ts
 * Gestionnaire de notifications toast (affichage temporaire).
 */

import { coerceStr } from './src/lib/coerceStr.ts';
import { escapeHtml } from './formatters.ts';

type ToastType = 'success' | 'info' | 'warning' | 'error' | 'shiny' | 'shadow' | 'legendary' | 'achievement';

export interface ToastOptions {
    title?: string;
    message?: string;
    type?: ToastType;
    icon?: string;
    duration?: number;
    closable?: boolean;
    html?: boolean;
}

type ToastStack = {
    container: HTMLElement;
    toasts: HTMLElement[];
};

const LEGENDARY_TOAST_MS = 5000;

export class ToastManager {
    rightStack: ToastStack;
    leftStack: ToastStack;
    maxToasts: number;

    constructor() {
        this.rightStack = {
            container: this.ensureContainer('toastContainer', 'toastContainer'),
            toasts: [],
        };
        this.leftStack = {
            container: this.ensureContainer('toastContainerLeft', 'toastContainer toastContainerLeft'),
            toasts: [],
        };

        const onContainerClick = (e: Event) => {
            const target = e.target;
            if (!(target instanceof Element)) return;
            const toastEl = target.closest('.toast');
            if (toastEl instanceof HTMLElement) {
                this.remove(toastEl);
            }
        };
        this.rightStack.container.addEventListener('click', onContainerClick);
        this.leftStack.container.addEventListener('click', onContainerClick);

        this.maxToasts = 5;
    }

    /** @deprecated use rightStack.container — kept for legacy callers */
    get container(): HTMLElement {
        return this.rightStack.container;
    }

    /** @deprecated use rightStack.toasts */
    get toasts(): HTMLElement[] {
        return this.rightStack.toasts;
    }

    ensureContainer(id: string, className: string): HTMLElement {
        let el = document.getElementById(id);
        if (!el) {
            el = document.createElement('div');
            el.id = id;
            el.className = className;
            document.body.appendChild(el);
        }
        return el;
    }

    // Escape-by-default (cf. AUDIT_SECURITE.md §3) : tout texte injecte dans
    // le toast est echappe sauf si l'appelant passe explicitement html: true.
    _esc(value: unknown): string {
        const text = coerceStr(value);
        return escapeHtml(text);
    }

    private stackForSide(side: 'right' | 'left'): ToastStack {
        return side === 'left' ? this.leftStack : this.rightStack;
    }

    show(options: ToastOptions): HTMLElement {
        return this.showOnSide('right', options);
    }

    showLeft(options: ToastOptions): HTMLElement {
        return this.showOnSide('left', options);
    }

    showOnSide(side: 'right' | 'left', options: ToastOptions): HTMLElement {
        const stack = this.stackForSide(side);
        const {
            title = '',
            message = '',
            type = 'info',
            icon = this.getDefaultIcon(type),
            duration = 3000,
            closable = true,
            html = false,
        } = options;

        if (stack.toasts.length >= this.maxToasts) {
            this.removeOldestInStack(stack);
        }

        const toast = document.createElement('div');
        toast.className = `toast toast-${type}${side === 'left' ? ' toast--left' : ''}`;
        const isPermanent = !(duration > 0);
        if (isPermanent) toast.dataset.permanent = '1';

        const safeTitle = html ? title : this._esc(title);
        const safeMessage = html ? message : this._esc(message);
        const safeIcon = html ? icon : this._esc(icon);

        toast.innerHTML = `
            ${safeIcon ? `<div class="toast-icon">${safeIcon}</div>` : ''}
            <div class="toast-content">
                ${safeTitle ? `<div class="toast-title">${safeTitle}</div>` : ''}
                ${safeMessage ? `<div class="toast-message">${safeMessage}</div>` : ''}
            </div>
            ${closable ? '<div class="toast-close">×</div>' : ''}
        `;

        stack.container.appendChild(toast);
        stack.toasts.push(toast);

        if (duration > 0) {
            setTimeout(() => this.remove(toast), duration);
        }

        return toast;
    }

    remove(toast: HTMLElement): void {
        if (!toast || !toast.parentElement || toast.dataset.removing) return;

        toast.dataset.removing = 'true';
        toast.classList.add('removing');

        setTimeout(() => {
            if (toast.parentElement) {
                toast.parentElement.removeChild(toast);
            }
            this.rightStack.toasts = this.rightStack.toasts.filter((t) => t !== toast);
            this.leftStack.toasts = this.leftStack.toasts.filter((t) => t !== toast);
        }, 300);
    }

    removeOldestInStack(stack: ToastStack): void {
        if (!stack.toasts.length) return;
        const oldestNonPermanent = stack.toasts.find((t) => t?.dataset?.permanent !== '1');
        if (oldestNonPermanent) this.remove(oldestNonPermanent);
    }

    removeOldest(): void {
        this.removeOldestInStack(this.rightStack);
    }

    removeAll(): void {
        [...this.rightStack.toasts, ...this.leftStack.toasts].forEach((toast) => this.remove(toast));
    }

    getDefaultIcon(type: ToastType): string {
        return '';
    }

    success(title: string, message: string, duration?: number, html?: boolean): HTMLElement {
        return this.show({ title, message, type: 'success', duration, html });
    }

    info(title: string, message: string, duration?: number, html?: boolean): HTMLElement {
        return this.show({ title, message, type: 'info', duration, html });
    }

    infoLeft(title: string, message: string, duration?: number, html?: boolean): HTMLElement {
        return this.showLeft({ title, message, type: 'info', duration, html });
    }

    warning(title: string, message: string, duration?: number, html?: boolean): HTMLElement {
        return this.show({ title, message, type: 'warning', duration, html });
    }

    error(title: string, message: string, duration?: number, html?: boolean): HTMLElement {
        return this.show({ title, message, type: 'error', duration, html });
    }

    shiny(title: string, message: string, duration?: number, html?: boolean): HTMLElement {
        return this.show({ title, message, type: 'shiny', duration: duration ?? 0, html });
    }

    shadow(title: string, message: string, duration?: number, html?: boolean): HTMLElement {
        return this.show({ title, message, type: 'shadow', duration: duration ?? 0, html });
    }

    legendary(title: string, message: string, duration?: number, html?: boolean): HTMLElement {
        return this.show({ title, message, type: 'legendary', duration: duration ?? LEGENDARY_TOAST_MS, html });
    }

    achievement(name: string, desc: string, rewards?: string): HTMLElement {
        const msgHtml =
            `<div class="toast-achievement-desc">${desc}</div>` +
            (rewards ? `<div class="toast-achievement-rewards">${rewards}</div>` : '');
        return this.show({
            title: name,
            message: msgHtml,
            type: 'achievement',
            icon: '',
            duration: 0,
            html: true,
        });
    }
}

let toastSingleton: ToastManager | null = null;

export function getToastManager(): ToastManager {
    if (!toastSingleton) {
        toastSingleton = new ToastManager();
        globalThis.toast = toastSingleton;
    }
    return toastSingleton;
}

/** Lazy singleton — avoids `document` access at module load (Vitest / SSR-safe). */
export const toast = new Proxy(Object.create(null) as ToastManager, {
    get(_target, prop: keyof ToastManager) {
        const inst = getToastManager();
        const value = inst[prop];
        if (typeof value === 'function') {
            return value.bind(inst);
        }
        return value;
    },
});
